import networkx as nx,itertools
atlas=nx.graph_atlas_g()
def trim(G):return nx.convert_node_labels_to_integers(G.subgraph([v for v,d in G.degree() if d]))
def key(G):return nx.weisfeiler_lehman_graph_hash(G)
empty=nx.Graph()
Fs={key(trim(G)):trim(G) for G in atlas};Fs=list(Fs.values())
# patterns H induced partitions; embedding noninduced within F
Hs=[]
for H in atlas:
 n=len(H)
 if n<3 or nx.is_bipartite(H):continue
 pats={}
 for b in range(1<<n):
  A=trim(H.subgraph([i for i in range(n) if b>>i&1]));B=trim(H.subgraph([i for i in range(n) if not b>>i&1]))
  pats[key(A),key(B)]=(A,B)
 if not any(len(A)==0 and nx.is_forest(B) and max(dict(B.degree()).values(),default=0)==1 for A,B in pats.values()):continue
 if not any(len(A)==0 and nx.is_tree(B) and max(dict(B.degree()).values(),default=0)==len(B)-1 for A,B in pats.values()):continue
 Hs.append((H,list(pats.values())))
print('Hs',len(Hs),'Fs',len(Fs),flush=True)
cache={}
def sub(A,F):
 k=key(A),key(F)
 if k not in cache:
  cache[k]=len(A)<=len(F) and A.number_of_edges()<=F.number_of_edges() and nx.algorithms.isomorphism.GraphMatcher(F,A).subgraph_is_monomorphic()
 return cache[k]
for H,pats in Hs:
 pats0=[B for A,B in pats if len(A)==0]
 ok=[F for F in Fs if not any(sub(B,F) for B in pats0)]
 pairs=[]
 for i,F in enumerate(ok):
  for J in ok[i:]:
   if not any(sub(A,F) and sub(B,J) for A,B in pats):pairs.append((F.number_of_edges(),J.number_of_edges()))
 if not pairs:continue
 me=max(a+b for a,b in pairs);mw=max(3.3*max(a,b)+min(a,b) for a,b in pairs)
 if all(3.3*max(a,b)+min(a,b)<mw-1e-8 for a,b in pairs if a+b==me):
  print('FOUND H',list(H.edges()),'pairs',set(pairs),'maxe',me,'best',mw,flush=True);break
else:print('none')

